async function api(path,options={}){
 const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(session?{'X-CSRF-Token':session.csrf}:{}),...options.headers};
 let res;try{res=await fetch('/api/'+path,{...options,headers,credentials:'same-origin',body:options.body?JSON.stringify(options.body):undefined});}catch{throw new Error('Нет связи с сервером. Введенный текст сохранен. Попробуйте еще раз.');}
 const data=await res.json().catch(()=>({error:'Сервер временно недоступен.'}));
 if(!res.ok){const e=new Error(data.error||'Не удалось выполнить операцию.');e.status=res.status;e.field=data.field;throw e;}return data;
}
async function collection(path,wanted=listLimit){
 let result=null,items=[];
 while(items.length<wanted){const size=Math.min(50,wanted-items.length),d=await api(path+(path.includes('?')?'&':'?')+'limit='+size+'&offset='+items.length);result={...d,items:[]};items.push(...d.items);if(!d.has_more||!d.items.length)break;}
 return {...result,items};
}
