function points(r){if(!r)return '—';if(r.value===null)return r.status==='submitted'?'На проверке':r.status==='calculation_error'?'Ошибка формулы':r.status==='recalculation_required'?'Требует пересчета':r.type==='calculated'?'Ожидает оценок':'Нет оценки';if(r.output_format==='pass_fail')return r.value?'Зачтено':'Не зачтено';return `${number(r.value)} / ${number(r.max)}`;}
