 const sessionActive=d.exams.length&&session.today>=d.exams[0].date&&session.today<=d.exams.at(-1).date;
 const l=sessionActive?nextExam:d.next,inRange=session.today>=session.schedule_range[0]&&session.today<=session.schedule_range[1];
 const ongoing=l&&Date.parse(`${l.date}T${l.start_time}:00+03:00`)<=Date.parse(session.now),remaining=(d.remaining_today||[]).filter(x=>x.lesson_id!==l?.lesson_id);
 const finished=!sessionActive&&d.today_lessons&&d.next?.date!==session.today;
 const state=finished?'На сегодня занятия закончились':!sessionActive&&!d.today_lessons?(inRange?'Сегодня нет пар':'Расписание на сегодня еще не опубликовано'):'';
