 return `<details class="schedule-filters" ${Object.keys(scheduleFilters).length?'open':''}><summary>Фильтры расписания${Object.keys(scheduleFilters).length?' · '+Object.keys(scheduleFilters).length:''}</summary><div class="schedule-filter-grid">${Object.entries(labels).map(([key,label])=>`<label class="field"><span>${label}</span><select data-schedule-filter="${key}"><option value="">Все</option>${options[key].map(value=>`<option value="${esc(value)}" ${scheduleFilters[key]===value?'selected':''}>${esc(value)}</option>`).join('')}</select></label>`).join('')}</div><button class="btn quiet" data-action="reset-schedule-filters">Сбросить фильтры</button></details>`;
