function examState(c){if(c.assessment_type==='none')return 'Без экзамена';if(!c.exam)return 'Дата экзамена уточняется';const ended=Date.parse(`${c.exam.date}T${c.exam.end_time}:00+03:00`)<=Date.parse(session.now);if(!ended)return `${fmt(c.exam.date,{day:'numeric',month:'long',year:'numeric'})} · ${c.exam.start_time}`;const result=c.summary?.find(x=>x.role==='exam');return result?.value!==null&&result?'Экзамен: '+points(result):'Экзамен прошел · ожидается публикация результата';}
function courseCard(c){const progress=c.summary?.find(r=>r.role==='progress');return `<a class="course-card" href="#subject/${enc(c.id)}"><div class="course-name"><h2>${esc(c.name)}</h2><p>${teacher()?`${c.course} курс · ${c.students} студентов` :esc(examState(c))}</p></div><div class="course-result"><strong>${teacher()?icon('chevron'):esc(points(progress))}</strong>${progress?.status==='partial'?'<span class="small muted">Промежуточный</span>':''}</div></a>`;}
function calendar(exams){
 if(!exams.length)return '';
 const months=[...new Set(exams.map(e=>e.date.slice(0,7)))];
 return `<div class="month-panels">${months.map(m=>{const first=m+'-01',start=(new Date(first+'T12:00:00Z').getUTCDay()+6)%7,count=new Date(Number(m.slice(0,4)),Number(m.slice(5)),0).getDate();return `<section class="month-card"><h2>${fmt(first,{month:'long',year:'numeric'})}</h2><div class="calendar-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span class="weekday">${x}</span>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:count},(_,i)=>{const date=m+'-'+String(i+1).padStart(2,'0'),events=exams.filter(e=>e.date===date);return events.length?`<a href="#examday/${date}" aria-label="${fmt(date)}, экзаменов: ${events.length}">${i+1}${events.length>1?`<span class="exam-count">${events.length}</span>`:''}</a>`:`<span>${i+1}</span>`;}).join('')}</div></section>`;}).join('')}</div>`;
}
function examRows(exams){return exams.map(e=>`<a class="exam-card card" href="#subject/${enc(e.subject_id)}"><div class="exam-day"><strong>${Number(e.date.slice(-2))}</strong><span>${fmt(e.date,{month:'short'})}</span></div><div><h3>${esc(e.subject_name)}</h3><p class="small muted">${fmt(e.date,{day:'numeric',month:'long',year:'numeric'})} · ${esc(e.start_time)}–${esc(e.end_time)}</p><p class="small muted">${esc(e.room)} · ${esc(e.teacher)}</p>${Date.parse(`${e.date}T${e.end_time}:00+03:00`)<=Date.parse(session.now)?'<p class="small muted">Экзамен завершен. Результат — в дисциплине.</p>':''}</div></a>`).join('');}
async function gradesView(){const tabs=`<div class="segmented"><button data-grades="courses" aria-pressed="${courseMode==='courses'}">Дисциплины</button><button data-grades="exams" aria-pressed="${courseMode==='exams'}">Экзамены</button></div>`;if(courseMode==='exams'){const e=await collection('exams',Infinity);return heading('Экзамены и сессия','Все назначенные экзамены и зачеты')+tabs+(e.items.length?calendar(e.items)+`<p class="calendar-hint">Нажмите на выделенную дату, чтобы открыть экзамены этого дня.</p><div class="stack">${examRows(e.items)}</div>`:empty('Экзамены пока не назначены'));}const d=await collection('courses?q='+enc(courseSearch));return heading(staff()?'Все дисциплины':teacher()?'Мои дисциплины':'Оценки и сессия',teacher()?'Выберите дисциплину, затем студента.':'Работы, расчетные результаты и аттестация')+tabs+`<form id="course-search" class="collection-tools"><div class="collection-search"><input name="q" aria-label="Найти дисциплину" placeholder="Найти дисциплину" value="${esc(courseSearch)}"><button class="btn" type="submit">Найти</button></div></form><div class="course-list">${d.items.map(courseCard).join('')||empty('Дисциплины не найдены')}</div>${d.has_more?'<button class="btn load-more" data-action="more">Показать еще</button>':''}`;}
function courseInfo(c){return `<div class="course-overview"><section class="card course-description"><h2>О дисциплине</h2><p class="spaced">${esc(c.description||'Информация о курсе пока не добавлена.')}</p><dl class="facts"><div><dt>Аттестация</dt><dd>${esc(c.assessment_label||'Не указана')}</dd></div><div><dt>Период</dt><dd>Осенний семестр 2026</dd></div></dl></section><section class="card teacher-card"><h2>Преподаватель</h2><a class="teacher-person" href="#teacher/${enc(c.teacher.teacher_id)}"><span class="avatar teacher-avatar">${esc(initial(c.teacher.full_name))}</span><div><h3>${esc(c.teacher.full_name)}</h3><p class="small muted">${esc(c.teacher.position||'Преподаватель')}</p></div></a><a class="contact-link" href="mailto:${esc(c.teacher.email)}">${icon('mail')}<span>${esc(c.teacher.email)}</span></a>${c.consultation||c.teacher.consultation?`<div class="consultation"><span class="small muted">Консультации</span><p>${esc(c.consultation||c.teacher.consultation)}</p><p class="small muted">Согласуйте время и тему консультации в чате курса или по почте.</p><a class="btn spaced" href="https://t.me/nastyusha_triff" target="_blank" rel="noopener noreferrer">Написать по поводу консультации</a></div>`:''}${button('Профиль преподавателя','#teacher/'+enc(c.teacher.teacher_id))}</section><section class="card resources-card"><h2>Ресурсы курса</h2>${(c.resources||[]).map(r=>`<div class="resource-item"><span class="resource-icon">${icon(r.icon||'book')}</span><div><h3>${esc(r.label)}</h3>${r.url&&/^https:\/\//.test(r.url)?`<a class="contact-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Открыть</a>`:'<p class="small muted">Ссылка еще не добавлена</p>'}</div></div>`).join('')}</section></div>`;}
function journalTable(j){const active=!!journalScenarioState;return `<table class="simple-journal inline-journal"><caption class="sr-only">Журнал оценок. Дедлайн и время оценки указаны по Москве.</caption><thead><tr><th scope="col">Наименование</th><th scope="col"><span class="score-heading">Оценка<button id="journal-calculator" class="icon-button calculator-toggle" data-action="journal-calculator" aria-label="${active?'Выключить':'Включить'} калькулятор оценок" aria-pressed="${active}" title="${active?'Вернуться к оценкам':'Посчитать предполагаемые оценки'}">${icon('calculator')}</button></span></th><th scope="col">Дедлайн</th><th scope="col">Оценено</th></tr></thead><tbody>${j.items.map(r=>`<tr class="${r.type==='calculated'?'calculated':''}"><th scope="row" title="${r.type==='calculated'?esc(r.formula):''}">${esc(r.title)}</th><td class="score-cell" ${r.type==='calculated'?`data-scenario-result="${esc(r.id)}"`:''}>${journalScore(r)}</td><td class="date-cell">${journalDate(r.due_at)}</td><td class="date-cell">${journalDate(r.graded_at)}</td></tr>`).join('')}</tbody></table><p id="journal-scenario-status" class="small muted scenario-status" role="status" aria-live="polite">${active?'Прогноз · не сохраняется':''}</p>`;}

