function fieldHtml(f,value){const v=value??f.default??'',id='field-'+f.key;const attrs=`id="${esc(id)}" name="${esc(f.key)}" ${f.required?'required':''} aria-describedby="${esc(id)}-hint" ${f.max_length?'maxlength="'+Number(f.max_length)+'"':''}`;return `<label class="field" for="${esc(id)}"><span>${esc(f.label)}${f.required?' *':''}</span>${f.type==='textarea'?`<textarea ${attrs} placeholder="${esc(f.placeholder||'')}">${esc(v)}</textarea>`:f.type==='select'?`<select ${attrs}>${f.options.map(o=>`<option value="${esc(o.value)}" ${o.value===v?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:`<input ${attrs} placeholder="${esc(f.placeholder||'')}" type="${esc(['text','email','tel','date','number'].includes(f.type)?f.type:'text')}" value="${esc(v)}" ${f.min!==undefined?'min="'+Number(f.min)+'"':''} ${f.max!==undefined?'max="'+Number(f.max)+'"':''}>`}<small id="${esc(id)}-hint">${esc(f.hint||'')}</small></label>`;}
