function newRequestView(){const d=draft('new')||{type:session.ui.request_types[0].id,fields:{},key:crypto.randomUUID()},type=session.ui.request_types.find(t=>t.id===d.type)||session.ui.request_types[0];draft('new',d);return back('requests','К заявкам')+heading('Новое обращение','Отправьте вопрос или закажите документ')+`<section class="card form-card"><form id="request-form"><label class="field"><span>Что нужно подготовить</span><select id="request-type" name="type">${session.ui.request_types.map(t=>`<option value="${esc(t.id)}" ${t.id===type.id?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label><p class="form-help">Заявитель: ${esc(session.user.full_name)} · ${esc(session.user.academic_group)}. Данные подставлены из профиля.</p><p class="required-note">* Обязательные поля</p>${type.fields.map(f=>fieldHtml(f,d.fields[f.key])).join('')}<p class="form-help">Срок подготовки и способ получения сообщит деканат после проверки обращения.</p><div class="form-error" role="alert"></div><section id="request-review" class="request-review" hidden></section><button class="btn primary" type="submit">Проверить обращение</button></form></section>`;}
async function requestView(id){const [r,h]=await Promise.all([api('requests/'+enc(id)),collection(`requests/${enc(id)}/history`)]),d=draft('reply:'+id)||{fields:{},key:crypto.randomUUID()};return back('requests','К заявкам')+heading(r.title,'Заявка '+requestNumber(r))+`<div class="request-detail"><div class="stack"><section class="card">${badge(r.status)}<div class="request-progress" aria-label="Текущий статус"><span class="${r.status==='submitted'?'current':''}">Отправлена</span><span class="${['in_progress','needs_info'].includes(r.status)?'current':''}">Обработка</span><span class="${['ready','closed'].includes(r.status)?'current':''}">Результат</span></div><h2>Что делать дальше</h2><p class="spaced request-body">${esc(r.next_action)}</p><dl class="request-info"><div><dt>Когда ждать</dt><dd>${r.status==='ready'?'Документ готов':r.status==='closed'?'Обращение закрыто':r.expected_ready_date?fmt(r.expected_ready_date,{day:'numeric',month:'long',year:'numeric'}):'Срок пока не назначен'}</dd></div><div><dt>Как получить результат</dt><dd>${esc(r.delivery_label|| (r.delivery_method==='pickup'?'Личное получение':'Ответ в портале'))}</dd></div>${r.pickup_location?`<div><dt>Место выдачи</dt><dd>${esc(r.pickup_location)}</dd></div>`:''}${r.pickup_hours?`<div><dt>Часы выдачи</dt><dd>${esc(r.pickup_hours)}</dd></div>`:''}</dl><div class="request-response"><h3>Ответ деканата</h3><p>${esc(r.response||'Ответа пока нет.')}</p></div>${(r.links||[]).filter(l=>/^(lesson|subject|request)\/[\w-]+$/.test(l.route)).map(l=>button(l.label,'#'+l.route)).join('')}${!staff()&&r.status==='needs_info'?`<form id="reply-form" data-id="${esc(id)}"><h2>Уточнить обращение</h2><p class="form-help">${esc(r.required_clarification)}</p>${r.clarification_fields.map(f=>fieldHtml(f,d.fields[f.key])).join('')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Отправить уточнение</button></form>`:''}</section>${staff()?staffReplyForm(r):''}<section class="card"><details ${staff()?'open':''}><summary><strong>История обращения</strong></summary><div class="history-list">${h.items.map(x=>`<div class="history-event"><span class="small">${stamp(x.occurred_at)} · ${esc(x.actor)}</span><p>${esc(x.message)}</p><span class="small">${esc(statusLabel(x.status))}</span></div>`).join('')}</div>${h.has_more?'<button class="btn load-more" data-action="more">Показать еще</button>':''}</details></section></div><section class="card"><h2>${staff()?'Обращение студента':'Ваше обращение'}</h2>${staff()?`<p class="spaced"><strong>${esc(r.student.full_name)}</strong></p><p class="small muted">${esc(r.student.academic_group)} · ${esc(r.student.email)}</p>`:''}${r.fields&&Object.keys(r.fields).length?requestFieldsHtml(r):`<p class="spaced request-body">${esc(r.description)}</p>`}<p class="small muted spaced">Отправлено ${stamp(r.created_at)}</p></section></div>`;}
async function notificationsView(){const d=await collection('notifications');return heading('Уведомления','Изменения, обращения, объявления и напоминания')+d.items.map(n=>`<article class="notice-row ${n.read?'':'unread'}"><span class="icon-button">${icon(n.kind==='schedule'?'schedule':n.kind==='request'?'requests':'bell')}</span><div class="notice-body"><h2>${esc(n.title)}</h2><p>${esc(n.body)}</p><p>${stamp(n.published_at)}</p><div class="notice-actions"><a class="plain-link" href="#${esc(n.route)}" data-notification="${esc(n.id)}">Открыть</a>${n.read?'<span class="small muted">Прочитано</span>':`<button class="read-button" data-read="${esc(n.id)}">Отметить прочитанным</button>`}</div></div></article>`).join('')+(d.items.length?'':empty('Новых уведомлений нет'))+(d.has_more?'<button class="btn load-more" data-action="more">Показать еще</button>':'');}
function profileView(){const u=session.user;return heading(u.full_name,staff()?'Профиль сотрудника деканата':teacher()?'Профиль преподавателя':'Профиль студента')+`<div class="profile-layout"><section class="card"><h2>${teacher()||staff()?'Работа в университете':'Обучение'}</h2><dl class="facts profile-facts">${(teacher()||staff()?[['Факультет',u.faculty],['Подразделение',u.department],['Должность',u.position],['Кабинет',u.office],['Приемные часы',u.consultation]]:[['Факультет',u.faculty],['Программа',u.program],['Курс',u.course],['Направления',u.track_names?u.track_names.split('|').join(' · '):'Не указаны'],['Академическая группа',u.academic_group],['Языковая группа',u.language_group]]).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'Не указано')}</dd></div>`).join('')}</dl>${teacher()?`<p class="spaced muted">${esc(u.bio||'')}</p><button class="btn spaced" data-action="edit-profile">Изменить приемные часы</button>`:''}</section><section class="card profile-contact"><div class="sectionhead"><h2>Контакты</h2><button class="btn quiet" data-action="edit-profile">Изменить</button></div><dl class="facts"><div><dt>Почта</dt><dd><a class="contact-value" href="mailto:${esc(u.email)}">${esc(u.email)}</a></dd></div><div><dt>Телефон</dt><dd>${esc(u.phone||'Не указан')}</dd></div></dl><button class="btn profile-logout" data-action="logout">${icon('exit')}Выйти из кабинета</button></section></div>`;}
async function render(){
 if(!session){login();return;}const n=++generation;const parts=route().split('/').map(decodeURIComponent),root=parts[0];
 shell('<div class="startup" aria-busy="true" role="status">Загружаем…</div>');
 try{session=await api('session');if(n!==generation)return;let content;if(root==='today')content=await todayView();else if(root==='schedule')content=await scheduleView();else if(root==='changes')content=await changesView();else if(root==='lesson')content=await lessonView(parts[1]);else if(root==='grades')content=await gradesView();else if(root==='subject')content=await subjectView(parts[1]);else if(root==='journal')content=await subjectView(parts[1],parts[2]);else if(root==='requests')content=await requestsView();else if(root==='new'){if(teacher()||staff())throw new Error('Заявки доступны только студентам.');content=newRequestView();}else if(root==='request')content=await requestView(parts[1]);else if(root==='notifications')content=await notificationsView();else if(root==='profile')content=profileView();else if(root==='teacher')content=await teacherView(parts[1]);else if(root==='announcements'){const d=await collection('announcements');content=back('today','На главную')+heading('Объявления')+announcementRows(d.items);}else if(root==='announcement'){const a=await api('announcements/'+enc(parts[1]));content=back('announcements','К объявлениям')+heading(a.title)+`<article class="card article"><p class="article-author">${esc(a.author)} · ${stamp(a.published_at)}</p><div class="article-body">${esc(a.body)}</div></article>`;}else if(root==='examday'){const d=await collection('exams',Infinity);content=back('grades','К сессии')+heading('Экзамены',fmt(parts[1],{day:'numeric',month:'long',year:'numeric'}))+`<div class="stack">${examRows(d.items.filter(e=>e.date===parts[1]))}</div>`;}else content=empty('Страница не найдена','Откройте нужный раздел в меню.');if(n!==generation)return;shell(content);document.querySelector('h1')?.focus({preventScroll:true});success='';}
 catch(e){if(n!==generation)return;if(e.status===401){session=null;login(e.message);return;}shell(heading(e.status===403?'Нет доступа':e.status===404?'Страница недоступна':'Не удалось открыть страницу')+`<div class="form-error" role="alert">${esc(e.message)}</div>${root==='request'?button('К моим заявкам','#requests'):button('На главную','#today')}${!e.status||e.status>=500?'<button class="btn" data-action="retry">Повторить</button>':''}`);}
}
function rememberForm(form){if(form.id==='request-form'){const values=Object.fromEntries(new FormData(form));const {type,...fields}=values;const old=draft('new');const changed=JSON.stringify(old?.fields)!==JSON.stringify(fields)||old?.type!==type;draft('new',{type,fields,key:changed?crypto.randomUUID():old?.key||crypto.randomUUID()});}else if(form.id==='reply-form'){const key='reply:'+form.dataset.id,old=draft(key),fields=Object.fromEntries(new FormData(form));draft(key,{fields,key:JSON.stringify(fields)===JSON.stringify(old?.fields)?old.key:crypto.randomUUID()});}}
async function submitForm(form,work){if(form.dataset.submitting)return;form.dataset.submitting='yes';const btn=form.querySelector('button[type=submit]'),label=btn.textContent,error=form.querySelector('.form-error');btn.disabled=true;btn.textContent='Сохраняем…';error.textContent='';try{await work();}catch(e){error.textContent=e.message;say(e.message);const invalid=e.field?form.elements.namedItem(e.field):null;if(invalid){invalid.setAttribute('aria-invalid','true');invalid.setCustomValidity(e.message);invalid.focus();}if(e.status===409&&form.id==='grade-form'){$('#grade-conflict').innerHTML='<button type="button" class="btn" data-action="check-conflict">Проверить актуальную оценку</button>';}}finally{delete form.dataset.submitting;if(btn.isConnected){btn.disabled=false;btn.textContent=label;}}}
function dialogMarkup(row){const saved=gradeDrafts.get(row.id),edit=saved||row.edit;const localTime=edit.graded_at?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(edit.graded_at)).replace(' ','T'):'';return `<dialog id="grade-dialog" aria-labelledby="grade-title"><div class="dialog-head"><h2 id="grade-title">Оценка за работу</h2><button class="icon-button" data-action="close-dialog" aria-label="Закрыть">×</button></div><p class="dialog-subtitle">${esc(row.title)} · ${esc(currentJournal.student.full_name)}</p><form id="grade-form"><label class="field"><span>Балл от 0 до ${number(row.max)}</span><input name="score" type="number" inputmode="decimal" step="any" min="0" max="${row.max}" value="${edit.score===null?'':esc(edit.score)}"><small>Пустое поле — нет оценки. Ноль — опубликованный нулевой балл.</small></label><label class="field"><span>Комментарий</span><textarea name="feedback" maxlength="2000">${esc(edit.feedback)}</textarea></label><label class="field"><span>Публикация, московское время</span><input name="published_at" type="datetime-local" value="${localTime}"><small>Пустое поле или прошедшая дата — опубликовать сейчас. Экзаменационная оценка откроется после экзамена.</small></label><div class="form-error" role="alert"></div><div id="grade-conflict"></div><div class="button-row"><button class="btn primary" type="submit">Сохранить оценку</button><button class="btn" type="button" data-action="close-dialog">Отмена</button></div></form><details class="grade-history"><summary>История исправлений</summary><div id="grade-history">Загружаем…</div></details></dialog>`;}
async function editGrade(id){editRow=currentJournal.items.find(r=>r.id===id);if(!editRow)return;document.querySelector('#grade-dialog')?.remove();document.body.insertAdjacentHTML('beforeend',dialogMarkup(editRow));$('#grade-dialog').showModal();$('#grade-dialog input').focus();try{const d=await api(`courses/${enc(currentCourse.id)}/grades/${enc(currentJournal.student.id)}/${enc(id)}/history`);const target=$('#grade-history');if(target)target.innerHTML=d.items.map(h=>`<p>${stamp(h.occurred_at)} · ${esc(h.actor)}<br>${h.old?.score??'Нет оценки'} → ${h.new.score??'Нет оценки'}<br>${esc(h.new.feedback)}</p>`).join('')||'<p class="muted">Исправлений пока нет.</p>';}catch(e){if($('#grade-history'))$('#grade-history').textContent=e.message;}}
function saveGradeDraft(){const form=$('#grade-form');if(form&&editRow){const values=Object.fromEntries(new FormData(form));gradeDrafts.set(editRow.id,{score:values.score===''?null:Number(values.score),feedback:values.feedback,graded_at:values.published_at?values.published_at+':00+03:00':null});}}
function closeDialog(){saveGradeDraft();const d=$('#grade-dialog');d?.close();d?.remove();}
document.addEventListener('input',event=>{const form=event.target.form;if(form?.id==='login-form')loginDraft=Object.fromEntries(new FormData(form));if(['request-form','reply-form'].includes(form?.id))rememberForm(form);if(form?.id==='grade-form')saveGradeDraft();});
document.addEventListener('change',event=>{if(event.target.dataset.scheduleFilter){const key=event.target.dataset.scheduleFilter;if(event.target.value)scheduleFilters[key]=event.target.value;else delete scheduleFilters[key];render();}if(event.target.id==='request-type'){rememberForm(event.target.form);render();}if(event.target.id==='schedule-date'&&event.target.value){scheduleDate=event.target.value;render();}});
document.addEventListener('submit',async event=>{
 const form=event.target;event.preventDefault();
 if(await managementSubmit(form))return;
 if(form.id==='login-form'){loginDraft=Object.fromEntries(new FormData(form));await submitForm(form,async()=>{await mutate('login',loginDraft);session=await api('session');loginDraft.password='';demoOpen=false;document.querySelector('#demo-dialog')?.close();scheduleFilters={};scheduleDate=session.today;gradeDrafts.clear();requestFilter=staff()?'all':'active';location.hash='today';await render();});}
 else if(form.id==='account-search'){accountSearch=new FormData(form).get('q');accountLimit=5;login();}
 else if(form.id==='request-search'){requestSearch=new FormData(form).get('q');listLimit=20;render();}
 else if(form.id==='course-search'){courseSearch=new FormData(form).get('q');listLimit=20;render();}
 else if(form.id==='request-form'){rememberForm(form);if(form.dataset.reviewed!=='yes'){reviewRequest(form);return;}const d=draft('new');await submitForm(form,async()=>{const r=await mutate('requests',{type:d.type,fields:d.fields},'POST',{'Idempotency-Key':d.key});draft('new',null);success='Обращение отправлено. Номер и дальнейшие шаги — в карточке.';location.hash='request/'+enc(r.request_id||r.id);await refreshSession();});}
 else if(form.id==='reply-form'){rememberForm(form);const key='reply:'+form.dataset.id,d=draft(key);await submitForm(form,async()=>{await mutate(`requests/${enc(form.dataset.id)}/reply`,{fields:d.fields},'POST',{'Idempotency-Key':d.key});draft(key,null);success='Уточнение доставлено. Статус изменит деканат после проверки.';await refreshSession();await render();});}
 else if(form.id==='grade-form'){saveGradeDraft();const d=gradeDrafts.get(editRow.id);await submitForm(form,async()=>{await mutate(`courses/${enc(currentCourse.id)}/grades/${enc(currentJournal.student.id)}/${enc(editRow.id)}`,{score:d.score,feedback:d.feedback,published_at:d.graded_at,version:editRow.edit.version},'PUT');gradeDrafts.delete(editRow.id);$('#grade-dialog').close();$('#grade-dialog').remove();success='Оценка сохранена. Зависимые показатели пересчитаны.';await render();});}
});
async function refreshSession(){try{session=await api('session');}catch(e){if(e.status===401){session=null;login(e.message);}}}
document.addEventListener('click',async event=>{
 const el=event.target.closest('button,a');if(!el)return;if(el.classList.contains('skip')){event.preventDefault();$('#main')?.focus();return;}
 try{
 if(await managementClick(el))return;
 if(el.dataset.action==='theme'){theme=theme==='dark'?'light':'dark';try{localStorage.setItem('portal-theme',theme);}catch{}applyTheme();document.querySelectorAll('.theme-switch').forEach(b=>b.outerHTML=themeButton());return;}
 if(el.dataset.action==='open-demo'){demoOpen=true;$('#demo-dialog').showModal();return;}
 if(el.dataset.action==='close-demo'){demoOpen=false;$('#demo-dialog').close();$('.demo-toggle').focus();return;}
 if(el.dataset.action==='reset-schedule-filters'){scheduleFilters={};render();return;}
 if(el.dataset.accountRole){accountRole=el.dataset.accountRole;accountSearch='';accountLimit=5;login();return;}
 if(el.dataset.action==='more-accounts'){accountLimit+=5;login();return;}
 if(el.dataset.account!==undefined){const a=accounts[Number(el.dataset.account)];loginDraft={username:a.username,password:a.password};demoOpen=false;login();$('#login-form button').focus();return;}
 if(el.dataset.week){scheduleDate=dayAdd(scheduleDate,Number(el.dataset.week));render();}
 if(el.dataset.date){scheduleDate=el.dataset.date;weekMode=false;render();}
 if(el.dataset.mode){weekMode=el.dataset.mode==='week';render();}
 if(el.dataset.grades){courseMode=el.dataset.grades;listLimit=20;render();}
 if(el.dataset.tab){courseTab=el.dataset.tab;render();}
 if(el.dataset.requestFilter){requestFilter=el.dataset.requestFilter;listLimit=20;render();}
 if(el.dataset.edit)await editGrade(el.dataset.edit);
 if(el.dataset.read){el.disabled=true;await mutate('notifications/'+enc(el.dataset.read)+'/read');await refreshSession();render();}
 if(el.dataset.notification){await mutate('notifications/'+enc(el.dataset.notification)+'/read');await refreshSession();}
 const action=el.dataset.action;
 if(action==='logout'){await mutate('logout');session=null;generation++;gradeDrafts.clear();currentJournal=null;currentCourse=null;closeDialog();location.hash='today';login();}
 if(action==='retry')render();
 if(action==='today-date'){scheduleDate=session.today;render();}
 if(action==='exams'){courseMode='exams';location.hash='grades';}
 if(action==='more'){listLimit+=20;render();}
 if(action==='close-dialog')closeDialog();
 if(action==='check-conflict'){
 const j=await api(`courses/${enc(currentCourse.id)}/journal?student_id=${enc(currentJournal.student.id)}&limit=50`),latest=j.items.find(r=>r.id===editRow.id);currentJournal=j;
 $('#grade-conflict').innerHTML=`<div class="conflict-comparison"><strong>Сейчас в журнале</strong><p>${latest.edit.score===null?'Нет оценки':number(latest.edit.score)+' / '+number(latest.max)}</p><p>${esc(latest.edit.feedback||'Без комментария')}</p><button class="btn" type="button" data-action="use-current">Редактировать актуальную версию</button><p>Ваш прежний вариант остается в полях выше, пока вы не выберете новую версию.</p></div>`;
 }
 if(action==='use-current'){const id=editRow.id;gradeDrafts.delete(id);await editGrade(id);}
 }catch(e){say(e.message);const err=document.querySelector('dialog .form-error')||document.querySelector('main .form-error');if(err)err.textContent=e.message;else{const main=$('#main');main?.insertAdjacentHTML('afterbegin',`<div class="form-error" role="alert">${esc(e.message)}</div>`);}el.disabled=false;}
});
document.addEventListener('cancel',e=>{if(e.target.id==='demo-dialog')demoOpen=false;if(e.target.id==='grade-dialog')saveGradeDraft();},true);
window.addEventListener('hashchange',()=>{closeDialog();gradeDrafts.clear();listLimit=20;courseTab=route().startsWith('journal/')?'journal':courseTabsMemory.get(decodeURIComponent(route().split('/')[1]||''))||'about';success=success||'';render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('pageshow',e=>{if(e.persisted){refreshSession().then(render);}});
(async()=>{try{accounts=(await api('accounts')).accounts;session=await api('session');scheduleDate=session.today;await render();}catch(e){session=null;login(e.status===401?'':e.message);}})();
